/**
 * GitHub API token resolution for the channel pack.
 *
 * Resolution order for authenticated REST calls:
 * 1. `credentials.token` / `credentials.installationToken` (explicit)
 * 2. GitHub App JWT → installation access token (when App creds + installation
 *    id are available — webhook `installation.id` or `GITHUB_APP_INSTALLATION_ID`)
 * 3. `GITHUB_TOKEN` / `GH_TOKEN` env (local PAT / fine-grained token)
 * 4. `gh auth token` (local CLI session)
 *
 * Production should set App credentials and omit ambient PATs. Local testing
 * can keep using a PAT or `gh auth login` when App creds are unset.
 */
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { createAppAuth } from "@octokit/auth-app";
import { isSecretRef } from "../../types.js";
const execFileAsync = promisify(execFile);
let ghAuthTokenCache = null;
const GH_AUTH_CACHE_MS = 5 * 60_000;
/** Refresh exported `GH_TOKEN` before installation tokens expire (~60m). */
const GH_CLI_TOKEN_REFRESH_MS = 50 * 60_000;
let ghCliTokenRefreshTimer = null;
/**
 * Resolve a credential value: a literal, a lazy getter, or a named secret
 * read from `process.env` (locally the shell; hosted, the bound deployment
 * secrets the runtime loads into the environment per request).
 */
export async function resolveCredentialValue(value) {
    if (value === undefined) {
        return undefined;
    }
    const resolved = typeof value === "function"
        ? await value()
        : isSecretRef(value)
            ? process.env[value.secretName]
            : value;
    if (typeof resolved !== "string") {
        return undefined;
    }
    const trimmed = resolved.trim();
    return trimmed === "" ? undefined : trimmed;
}
/** True when App id + private key are configured (credentials or env). */
export async function hasGitHubAppCredentials(credentials) {
    try {
        await resolveGitHubAppId(credentials?.appId);
        await resolveGitHubPrivateKey(credentials?.privateKey);
        return true;
    }
    catch {
        return false;
    }
}
/**
 * Resolve an installation id from the call site, then
 * `GITHUB_APP_INSTALLATION_ID` (host / non-webhook GitHub calls).
 */
export async function resolveGitHubInstallationId(installationId) {
    if (installationId !== undefined && Number.isInteger(installationId) && installationId > 0) {
        return installationId;
    }
    const fromEnv = await resolveCredentialValue(process.env.GITHUB_APP_INSTALLATION_ID);
    if (fromEnv === undefined) {
        return undefined;
    }
    if (!/^[1-9][0-9]*$/u.test(fromEnv)) {
        return undefined;
    }
    return Number(fromEnv);
}
/**
 * Resolve a bearer token for GitHub REST calls. Prefer explicit credentials,
 * then App installation tokens when configured, then local PAT / `gh auth`.
 */
export async function resolveGitHubAccessToken(input) {
    const explicit = (await resolveCredentialValue(input.credentials?.token)) ??
        (await resolveCredentialValue(input.credentials?.installationToken));
    if (explicit !== undefined) {
        return explicit;
    }
    const installationId = await resolveGitHubInstallationId(input.installationId);
    if (installationId !== undefined && (await hasGitHubAppCredentials(input.credentials))) {
        return createGitHubInstallationToken({
            api: input.api,
            appId: input.credentials?.appId,
            installationId,
            privateKey: input.credentials?.privateKey,
        });
    }
    const fromEnv = (await resolveCredentialValue(process.env.GITHUB_TOKEN)) ??
        (await resolveCredentialValue(process.env.GH_TOKEN));
    if (fromEnv !== undefined) {
        return fromEnv;
    }
    const fromGh = await tryResolveGhAuthToken();
    if (fromGh !== undefined) {
        return fromGh;
    }
    throw new Error("githubChannel: no GitHub token available (set GITHUB_APP_ID + GITHUB_APP_PRIVATE_KEY + installation id, or GITHUB_TOKEN / GH_TOKEN, or run `gh auth login`).");
}
/** Soft resolve — returns undefined instead of throwing. */
export async function tryResolveGitHubAccessToken(input) {
    try {
        return await resolveGitHubAccessToken(input);
    }
    catch {
        return undefined;
    }
}
/** Read `gh auth token` when the CLI is logged in. Cached briefly. */
export async function tryResolveGhAuthToken() {
    if (ghAuthTokenCache !== null && Date.now() < ghAuthTokenCache.expiresAtMs) {
        return ghAuthTokenCache.token;
    }
    try {
        const { stdout } = await execFileAsync("gh", ["auth", "token"], {
            timeout: 5_000,
            env: process.env,
        });
        const token = stdout.trim();
        if (token === "") {
            return undefined;
        }
        ghAuthTokenCache = {
            token,
            expiresAtMs: Date.now() + GH_AUTH_CACHE_MS,
        };
        return token;
    }
    catch {
        return undefined;
    }
}
export async function resolveGitHubAppId(appId) {
    const source = appId ??
        (process.env.GITHUB_APP_ID !== undefined && process.env.GITHUB_APP_ID !== ""
            ? process.env.GITHUB_APP_ID
            : undefined);
    if (source === undefined) {
        throw new Error("githubChannel: GITHUB_APP_ID is required.");
    }
    if (typeof source === "number") {
        return String(source);
    }
    const value = await resolveCredentialValue(source);
    if (value === undefined) {
        throw new Error("githubChannel: GITHUB_APP_ID is required.");
    }
    return value;
}
export async function resolveGitHubPrivateKey(privateKey) {
    const source = privateKey ??
        (process.env.GITHUB_APP_PRIVATE_KEY !== undefined && process.env.GITHUB_APP_PRIVATE_KEY !== ""
            ? process.env.GITHUB_APP_PRIVATE_KEY
            : undefined);
    if (source === undefined) {
        throw new Error("githubChannel: GITHUB_APP_PRIVATE_KEY is required.");
    }
    const value = await resolveCredentialValue(source);
    if (value === undefined) {
        throw new Error("githubChannel: GITHUB_APP_PRIVATE_KEY is required.");
    }
    return value.replace(/\\n/gu, "\n");
}
/**
 * Mint an installation access token via `@octokit/auth-app`.
 * Prefer {@link createGitHubOctokit} for normal API work — this is for
 * callers that only need the raw token string.
 */
export async function createGitHubInstallationToken(input) {
    const appId = await resolveGitHubAppId(input.appId);
    const privateKey = await resolveGitHubPrivateKey(input.privateKey);
    // Prefer createGitHubOctokit for API work — this path only mints a raw
    // token. Custom fetch belongs on the Octokit client, not createAppAuth
    // (StrategyOptions.request expects a full RequestInterface).
    const auth = createAppAuth({
        appId,
        privateKey,
        ...(input.api?.apiBaseUrl === undefined ? {} : { baseUrl: input.api.apiBaseUrl }),
    });
    try {
        const result = await auth({
            type: "installation",
            installationId: input.installationId,
        });
        return result.token;
    }
    catch (error) {
        throw installationTokenMintError(error, {
            appId,
            installationId: input.installationId,
        });
    }
}
/**
 * Octokit's bare mint failure ("Not Found - <docs url>") names neither the
 * app nor the installation, which makes a revoked installation or an
 * app/installation credential mismatch undiagnosable from production logs.
 * Rewrap with both ids and, for 404, the two causes that produce it.
 */
function installationTokenMintError(error, context) {
    const status = typeof error === "object" &&
        error !== null &&
        "status" in error &&
        typeof error.status === "number"
        ? error.status
        : undefined;
    const detail = error instanceof Error ? error.message : String(error);
    const hint = status === 404
        ? " — the installation does not exist for this app: it was uninstalled or suspended, or the configured app credentials belong to a different GitHub App than the one this installation id refers to"
        : "";
    const wrapped = new Error(`githubChannel: failed to mint an installation access token (app ${context.appId}, installation ${context.installationId}): ${detail}${hint}`, error instanceof Error ? { cause: error } : undefined);
    if (status !== undefined) {
        wrapped.status = status;
    }
    return wrapped;
}
/**
 * Export the resolved host GitHub token as `process.env.GH_TOKEN` so
 * subprocesses that shell out to `gh` work on App-credential hosts (corp
 * agent-serve). Intended for serve warmup when auth source is `app`.
 * Returns whether `GH_TOKEN` was written; refreshes on an interval.
 */
export async function ensureGhCliTokenEnv() {
    const token = await tryResolveGitHubAccessToken({});
    if (token === undefined) {
        return false;
    }
    process.env.GH_TOKEN = token;
    if (ghCliTokenRefreshTimer === null) {
        const timer = setInterval(() => {
            void ensureGhCliTokenEnv();
        }, GH_CLI_TOKEN_REFRESH_MS);
        timer.unref?.();
        ghCliTokenRefreshTimer = timer;
    }
    return true;
}
/** Clears in-memory caches. Intended for tests. */
export function clearGitHubAuthCaches() {
    ghAuthTokenCache = null;
    if (ghCliTokenRefreshTimer !== null) {
        clearInterval(ghCliTokenRefreshTimer);
        ghCliTokenRefreshTimer = null;
    }
}
